import pytest
from isort.setuptools_commands import ISortCommand

class MockDistribution:
    def __init__(self, packages=None, package_dir=None, py_modules=None):
        self.packages = packages or []
        self.package_dir = package_dir or {}
        self.py_modules = py_modules or []

class TestISortCommand:
    def test_distribution_files_with_packages(self):
        command = ISortCommand()
        command.distribution = MockDistribution(
            packages=["pkg1", "pkg2"],
            package_dir={"pkg1": "src/pkg1", "pkg2": "src/pkg2"}
        )
        assert list(command.distribution_files()) == ["src/pkg1", "src/pkg2", "setup.py"]

    def test_distribution_files_with_packages_and_empty_package_dir(self):
        command = ISortCommand()
        command.distribution = MockDistribution(
            packages=["pkg1"],
            package_dir={}
        )
        assert list(command.distribution_files()) == ["pkg1", "setup.py"]

    def test_distribution_files_with_py_modules(self):
        command = ISortCommand()
        command.distribution = MockDistribution(
            packages=[],
            py_modules=["module1", "module2"]
        )
        assert list(command.distribution_files()) == ["module1.py", "module2.py", "setup.py"]

    def test_distribution_files_with_no_packages_or_modules(self):
        command = ISortCommand()
        command.distribution = MockDistribution()
        assert list(command.distribution_files()) == ["setup.py"]

if __name__ == "__main__":
    pytest.main()

import pytest
from isort._vendored.tomli._parser import Flags

def test_is_empty_key():
    instance = Flags()
    assert instance.is_([], 1) == False

def test_is_non_existing_key():
    instance = Flags()
    instance._flags = {}
    assert instance.is_(['non-existing-key'], 1) == False

def test_is_key_with_no_flags():
    instance = Flags()
    instance._flags = {
        'key1': {
            'flags': [],
            'recursive_flags': [],
            'nested': {}
        }
    }
    assert instance.is_(['key1'], 1) == False

def test_is_key_with_flags():
    instance = Flags()
    instance._flags = {
        'key1': {
            'flags': [1, 2],
            'recursive_flags': [],
            'nested': {}
        }
    }
    assert instance.is_(['key1'], 1) == True

def test_is_key_with_recursive_flags():
    instance = Flags()
    instance._flags = {
        'key1': {
            'flags': [],
            'recursive_flags': [1],
            'nested': {}
        }
    }
    assert instance.is_(['key1'], 1) == True

def test_is_non_existing_nested_key():
    instance = Flags()
    instance._flags = {
        'key1': {
            'flags': [],
            'recursive_flags': [],
            'nested': {
                'nested_key': {
                    'flags': [],
                    'recursive_flags': []
                }
            }
        }
    }
    assert instance.is_(['key1', 'non_existent_nested_key'], 1) == False

def test_is_nested_key_with_flags():
    instance = Flags()
    instance._flags = {
        'key1': {
            'flags': [],
            'recursive_flags': [],
            'nested': {
                'nested_key': {
                    'flags': [1],
                    'recursive_flags': []
                }
            }
        }
    }
    assert instance.is_(['key1', 'nested_key'], 1) == True

import pytest
from isort._vendored.tomli._parser import parse_key

def test_parse_key_single_component():
    assert parse_key('keyname', 0) == (1, ['keyname'])

def test_parse_key_multiple_components():
    assert parse_key('key1.key2.key3', 0) == (12, ['key1', 'key2', 'key3'])

def test_parse_key_with_leading_whitespace():
    assert parse_key('  key1.key2', 0) == (10, ['key1', 'key2'])

def test_parse_key_edge_case_empty():
    assert parse_key('', 0) == (0, [''])

def test_parse_key_with_dot_at_end():
    assert parse_key('key1.key2.', 0) == (12, ['key1', 'key2'])

def test_parse_key_invalid_character():
    assert parse_key('key1$key2', 0) == (5, ['key1'])
